  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/proc/cygdrive/c/Users/shivs/Downloads/old_laptop/180_Days_learning_advance_backend/Day_1_caching/04-otp-login-ttl/node_modules/.pnpm/bun@1.3.14/node_modules/bun/node_modules:/proc/cygdrive/c/Users/shivs/Downloads/old_laptop/180_Days_learning_advance_backend/Day_1_caching/04-otp-login-ttl/node_modules/.pnpm/bun@1.3.14/node_modules:/proc/cygdrive/c/Users/shivs/Downloads/old_laptop/180_Days_learning_advance_backend/Day_1_caching/04-otp-login-ttl/node_modules/.pnpm/node_modules"
